package com.example.inventory.models; public class Item{private int id,quantity,vendorId;private String name;public Item(){}public Item(int id,String name,int quantity,int vendorId){this.id=id;this.name=name;this.quantity=quantity;this.vendorId=vendorId;}public int getId(){return id;}public void setId(int v){id=v;}public String getName(){return name;}public void setName(String v){name=v;}public int getQuantity(){return quantity;}public void setQuantity(int v){quantity=v;}public int getVendorId(){return vendorId;}public void setVendorId(int v){vendorId=v;}public String toString(){return id+" - "+name+" ("+quantity+")";}}